/* ===== Buttons Css ===== */
.call-action-one .call-action-content .call-action-btn .primary-btn {
  background: var(--primary);
  color: var(--white);
  box-shadow: var(--shadow-2);
}
.call-action-one .call-action-content .call-action-btn .active.primary-btn, .call-action-one .call-action-content .call-action-btn .primary-btn:hover, .call-action-one .call-action-content .call-action-btn .primary-btn:focus {
  background: var(--primary-dark);
  color: var(--white);
  box-shadow: var(--shadow-4);
}
.call-action-one .call-action-content .call-action-btn .deactive.primary-btn {
  background: var(--gray-4);
  color: var(--dark-3);
  pointer-events: none;
}

/*===== call action one =====*/
.call-action-one {
  background-color: var(--light-2);
  padding-top: 50px;
  padding-bottom: 100px;
}
.call-action-one .call-action-content .call-action-text {
  margin-top: 50px;
}
.call-action-one .call-action-content .call-action-text .action-title {
  font-weight: 600;
  color: var(--black);
}
.call-action-one .call-action-content .call-action-text .text-lg {
  color: var(--dark-3);
  margin-top: 16px;
}
.call-action-one .call-action-content .call-action-btn {
  margin-top: 50px;
}

/*===== CALL TO ACTION STYLE 2 =====*/
.primary-btn { background: var(--secondary); color: var(--white); box-shadow: var(--shadow-2); padding: 12px 26px; border-radius: 6px; font-weight: 600; border: none; }
.primary-btn:hover { background: var(--secondary-dark); color: var(--white); box-shadow: var(--shadow-4); }
.outline-btn { border: 1.5px solid var(--secondary); color: var(--secondary); padding: 11px 24px; border-radius: 6px; font-weight: 600; background: transparent; }
.outline-btn:hover { background: var(--secondary); color: var(--white); }
.call-to-actions-style-3 { background: var(--light-2); padding: 80px 0; }
.call-to-actions-style-3 .banner-wrap { background: var(--white); border: 1px solid var(--gray-4); border-radius: 16px; padding: 48px 36px; box-shadow: var(--shadow-3); }
.call-to-actions-style-3 .eyebrow { color: var(--secondary); font-weight: 600; font-size: 14px; text-transform: uppercase; letter-spacing: .05em; }
.call-to-actions-style-3 h2, .call-to-actions-style-3 h3 { color: var(--black); }
.call-to-actions-style-3 p { color: var(--dark-2); }
.call-to-actions-style-3 .stat-panel { padding: 32px; border-radius: 12px; background: var(--light-2); border: 1px solid var(--gray-4); text-align: center; }

